#define main original_previous_named_main
#include "../named-probe/parity_previous_named.c"
#undef main
#include <sys/wait.h>
#include <unistd.h>
static void select_a(const char *self,const char *path){fflush(stdout);pid_t p=fork();need(p>=0,"fork A setter");if(!p){execl(self,self,"--setter",path,(char*)NULL);_exit(127);}int status;need(waitpid(p,&status,0)==p&&WIFEXITED(status)&&!WEXITSTATUS(status),"A setter");}
static void recreated(const char *self,const char *path,int changed){need(!mkdir(path,0700),"recreated mkdir");MDB_env *e=open_env(path,MDB_NOTLS);MDB_txn *t=begin(e,0);MDB_dbi x=db(t,"x",MDB_CREATE);ok(mdb_set_compare(t,x,bytes_compare),"A X comparator");put(t,x,"k","A");ok(mdb_txn_commit(t),"A commit");t=begin(e,0);ok(mdb_drop(t,x,1),"delete old DBI");/* x is closed and never used again. */MDB_dbi y=db(t,"x",MDB_CREATE|(changed?MDB_DUPSORT:0));ok(mdb_set_compare(t,y,bytes_compare),"B X comparator");put(t,y,"k","B");ok(mdb_txn_commit(t),"B recreated commit");MDB_txn *held=begin(e,MDB_RDONLY);MDB_val k=val("k"),v;ok(mdb_get(held,y,&k,&v),"held B");MDB_cursor *c;ok(mdb_cursor_open(held,y,&c),"held B cursor");ok(mdb_cursor_get(c,&k,&v,MDB_SET),"held B position");select_a(self,path);t=begin(e,MDB_RDONLY);need(mdb_txn_id(t)==1,"recreated A id");MDB_dbi a=db(t,"x",0);need(a==y,"existing X alias");flags(t,a,changed?MDB_DUPSORT:0,"recreated.flags.before-load");k=val("k");int rc=mdb_get(t,a,&k,&v);printf("recreated.get=%d",rc);if(!rc)printf(" value=%.*s",(int)v.mv_size,(char*)v.mv_data);putchar('\n');need(changed?rc==MDB_INCOMPATIBLE:(!rc&&v.mv_size==1&&*(char*)v.mv_data=='A'),"same name projected A identity/flags");mdb_txn_abort(t);
    /* Check B while A is only a read view, then end it before branching writes:
     * upstream rewinds physical allocation and does not preserve newer B pages. */
    ok(mdb_cursor_get(c,&k,&v,MDB_GET_CURRENT),"held B after A read");need(v.mv_size==1&&*(char*)v.mv_data=='B',"held B bytes after A read");mdb_cursor_close(c);mdb_txn_abort(held);
    if(!changed){
        t=begin(e,0);MDB_txn *child;ok(mdb_txn_begin(e,t,0,&child),"projected child");put(child,y,"k","child");ok(mdb_txn_commit(child),"projected child release");value(t,y,"k","child","projected.child.release");ok(mdb_txn_begin(e,t,0,&child),"projected child abort begin");put(child,y,"k","aborted");mdb_txn_abort(child);value(t,y,"k","child","projected.child.abort");MDB_val rk=val("r"),reserved={2,NULL};ok(mdb_put(t,y,&rk,&reserved,MDB_RESERVE),"projected reserve");memcpy(reserved.mv_data,"RR",2);value(t,y,"r","RR","projected.reserve");ok(mdb_txn_prepare(t),"projected prepare");ok(mdb_txn_commit(t),"projected commit");
        t=begin(e,MDB_RDONLY);value(t,y,"k","child","projected.canonical");value(t,y,"r","RR","projected.canonical.reserve");comparator(t,y);mdb_txn_abort(t);
    }
    if(!changed){t=begin(e,0);ok(mdb_drop(t,y,0),"projected named clear");ok(mdb_txn_commit(t),"projected clear commit");t=begin(e,MDB_RDONLY);value(t,y,"k",NULL,"projected.clear");mdb_txn_abort(t);t=begin(e,0);ok(mdb_drop(t,y,1),"projected named delete");/* y is closed and never used again. */MDB_dbi recreated=db(t,"x",MDB_CREATE);ok(mdb_set_compare(t,recreated,bytes_compare),"recreated comparator");put(t,recreated,"k","recreated");ok(mdb_txn_commit(t),"projected delete/recreate commit");mdb_env_close(e);e=open_env(path,MDB_RDONLY|MDB_NOTLS);t=begin(e,MDB_RDONLY);recreated=db(t,"x",0);ok(mdb_set_compare(t,recreated,bytes_compare),"reopen comparator");value(t,recreated,"k","recreated","projected.reopen");mdb_txn_abort(t);}
    mdb_env_close(e);}
static void collision(const char *self,const char *path){need(!mkdir(path,0700),"collision mkdir");MDB_env *e=open_env(path,MDB_NOTLS);MDB_txn *t=begin(e,0);MDB_dbi main=db(t,NULL,0);char name[]="future";MDB_val k={sizeof name,name},v=val("user");ok(mdb_put(t,main,&k,&v,0),"A ordinary row");ok(mdb_txn_commit(t),"A collision commit");t=begin(e,0);ok(mdb_del(t,main,&k,NULL),"remove ordinary row");MDB_dbi future=db(t,"future",MDB_CREATE);put(t,future,"k","B");ok(mdb_txn_commit(t),"B named commit");select_a(self,path);t=begin(e,MDB_RDONLY);MDB_dbi a=db(t,"future",0);need(a==future,"collision alias");k=val("k");int rc=mdb_get(t,a,&k,&v);printf("collision.get=%d\n",rc);need(rc==MDB_INCOMPATIBLE,"A ordinary MAIN row is not subdata");mdb_txn_abort(t);mdb_env_close(e);}
int main(int argc,char **argv){if(argc==3&&!strcmp(argv[1],"--setter")){MDB_env *e=open_env(argv[2],MDB_RDONLY|MDB_PREVSNAPSHOT|MDB_NOTLS);mdb_env_close(e);return 0;}if(argc!=2)return 2;need(!mkdir(argv[1],0700)||errno==EEXIST,"recreated root");for(int changed=0;changed<2;changed++){char path[4096];int n=snprintf(path,sizeof path,"%s/changed%d",argv[1],changed);need(n>0&&(size_t)n<sizeof path,"recreated path");printf("scenario=G03-recreated-named-flags%d\n",changed);recreated(argv[0],path,changed);}char path[4096];int n=snprintf(path,sizeof path,"%s/collision",argv[1]);need(n>0&&(size_t)n<sizeof path,"collision path");puts("scenario=G03-ordinary-main-collision");collision(argv[0],path);puts("previous-recreated-named-complete journeys=3");return 0;}
